import sys

def strip_kotlin_comments(src):
    out = []
    i = 0
    n = len(src)
    state = 'CODE'
    block_depth = 0
    while i < n:
        c = src[i]
        if state == 'CODE':
            if src.startswith('"""', i):
                state = 'TSTRING'; out.append('"""'); i += 3; continue
            if c == '"':
                state = 'STRING'; out.append(c); i += 1; continue
            if c == "'":
                state = 'CHAR'; out.append(c); i += 1; continue
            if c == '/' and i + 1 < n:
                nxt = src[i + 1]
                if nxt == '/':
                    state = 'LINE'; i += 2; continue
                elif nxt == '*':
                    state = 'BLOCK'; block_depth = 1; i += 2; continue
            out.append(c); i += 1
        elif state == 'LINE':
            if c == '\n':
                out.append('\n'); state = 'CODE'
            i += 1
        elif state == 'BLOCK':
            if c == '*' and i + 1 < n and src[i + 1] == '/':
                block_depth -= 1
                if block_depth == 0:
                    state = 'CODE'
                i += 2
            elif c == '/' and i + 1 < n and src[i + 1] == '*':
                block_depth += 1; i += 2
            else:
                if c == '\n':
                    out.append('\n')
                i += 1
        elif state in ('STRING', 'CHAR'):
            close = '"' if state == 'STRING' else "'"
            if c == '\\':
                out.append(c)
                if i + 1 < n:
                    out.append(src[i + 1]); i += 2; continue
                i += 1; continue
            if c == close:
                state = 'CODE'; out.append(c); i += 1
            else:
                out.append(c); i += 1
        elif state == 'TSTRING':
            if c == '\\':
                out.append(c)
                if i + 1 < n:
                    out.append(src[i + 1]); i += 2; continue
                i += 1; continue
            if src.startswith('"""', i):
                state = 'CODE'; out.append('"""'); i += 3
            else:
                out.append(c); i += 1
    result = ''.join(out)
    return '\n'.join(ln.rstrip() for ln in result.split('\n'))

with open(sys.argv[1], 'r', encoding='utf-8') as f:
    src = f.read()
with open(sys.argv[2], 'w', encoding='utf-8') as f:
    f.write(strip_kotlin_comments(src))

