import numpy as np, glob, os
from PIL import Image
files = sorted(glob.glob('mixed/*.png'))
def load(f):
    return np.asarray(Image.open(f).convert('RGB')).astype(np.float32)/255.
cache = {f: load(f) for f in files}
def fam(f):
    n = os.path.basename(f)
    for pref in ['WoodPlanksPainted','WoodPlanks','Wood_wall_Slits','WoodLogs','WoodRoof','Wood02']:
        if n.startswith(pref): return 'wood'
    for pref in ['Fabric_','Facades_','Metal_','Tiles_']:
        if n.startswith(pref): return pref[:-1].lower()
    return 'other'
fams = {}
for f in files: fams.setdefault(fam(f), []).append(f)
import itertools
for name, fs in sorted(fams.items()):
    for a,b in itertools.combinations(fs,2):
        A,B = cache[a], cache[b]
        if A.shape != B.shape: continue
        # correlations: direct, G-flipped, vertically flipped, both
        ca = float((A[:,:,1]*B[:,:,1]).mean())
        cf = float(((1-A[:,:,1])*(1-B[:,:,1])).mean())  # G-flip both
        Bvf = B[::-1].copy()
        cv = float((A[:,:,1]*Bvf[:,:,1]).mean())
        cvf = float(((1-A[:,:,1])*(1-Bvf[:,:,1])).mean())
        if max(ca,cf,cv,cvf) > 0.75:
